# ------------------------------------------------------------------ 23 Motion design
def ch23():
    MO = '11_MOTION_GRAPHICS/'
    KF = MO + 'Exports/Key_Frames/'
    P = []
    P.append(divider('23', 'Motion <span class="lit">design</span>.', 'Light, not bounce. A gold point travels a beam through the dark room and whatever it passes is revealed. Four durations, four curves, left to right, arrive fast and settle long.',
        [('23.1', 'Principles and the timing scale'), ('23.2', 'Easing curves'), ('23.3', 'Logo reveal and outro · key frames'), ('23.4', 'Lower thirds, intro, outro, transition'), ('23.5', 'Logo animation rules and delivery')], '23 · Motion design'))
    tm = table(['Token', 'Duration', 'Use'], [('<span class="mono">--t-fast</span>', '<b>200 ms</b>', 'A point appears, a word arrives, a hover responds, a stroke fades after a fill'), ('<span class="mono">--t</span>', '<b>400 ms</b>', 'The standard entrance: a line rises, a label settles, a letter blooms, an element sinks out'),
                                               ('<span class="mono">--t-slow</span>', '<b>800 ms</b>', 'The lamp rises, a beam grows, a glow pulses once, a plate wipes in'), ('<span class="mono">--t-reveal</span>', '<b>1100 ms</b>', 'The reveal: the point travels the full beam, the light wipes a quote, photography settles')], widths=['22mm', '18mm', 'auto'])
    pr = rules(['<b>One thing moves.</b> A composition has one travelling element at a time — the point, the light, a line arriving. Letters, labels and lines follow the light.', '<b>Left → right, top → down.</b> The beam travels in reading direction; the lamp rises from above. Nothing enters from the right; nothing moves backwards.',
                '<b>Arrive fast, settle long.</b> The first 200 ms do most of the work; the rest is a settle the eye can rest on.', '<b>Reveal by light.</b> Things are not animated in; they are lit. A letter appears because the point passed it.',
                '<b>Glow is gold and belongs to the point.</b> Letters, type and photographs never glow, blur or cast coloured light.', '<b>Holds are calm.</b> Once arrived, nothing moves for at least 1.2 s before a piece ends. No idle motion, no floating, no slow zoom.',
                '<b>Exits are quieter than entrances.</b> 400 ms on --ease-in with a 12 px sink. Nothing flies out.', '<b>Real copy, real rooms.</b> Wall labels on every image; sentence-case headlines; one lit word at most.'], cls='tight')
    poster = fig(A(MO + 'Logo_Animations/sanzeed-logo-reveal--dark-1920x1080--poster.jpg', 1200), 'Logo reveal · hold frame', '4 s · 1920×1080 · the poster of every video is its final hold', None, plate='dark cover', h='h44')
    P.append(page('23 · Motion design', head('23.1 · Principles and the timing scale', 'Light, not <span class="lit">bounce</span>.', 'Light has no mass. It does not overshoot, spring, wobble, spin or stretch. It arrives quickly and settles slowly; it glows; it leaves without a sound. From 11_MOTION_GRAPHICS/Motion_Principles.md.') + body(f'<div class="split even"><div>{tm}<p class="sm mt-2 muted">Staggers: words 160 ms apart, lines 150 ms; the four steps of the route light when the light reaches them. In a 4 s reveal 1.2 s is hold; in a 5 s lower third 2.9 s is hold.</p>{poster.replace("fig ", "fig mt-3 ")}</div><div>{pr}</div></div>')))
    ez = fig(A(MO + 'Exports/Motion_Principles/sanzeed-motion--easing-curves.png', 1800), 'Easing curves and the timing scale', 'Exports/Motion_Principles/sanzeed-motion--easing-curves.png · source easing-curves.html', None, plate='dark', h='h80')
    et = table(['Token', 'Curve', 'Character', 'Use'], [('<span class="mono">--ease</span>', '<span class="tnum">cubic-bezier(.22, .8, .2, 1)</span>', '<b>Light.</b> 75 % of the distance in the first quarter of the time; the rest is settle', 'Every entrance, every travel of the point. The default'),
                                                        ('<span class="mono">--ease-in</span>', '<span class="tnum">cubic-bezier(.6, 0, .9, .4)</span>', 'Gathers speed and leaves', 'Exits only'), ('<span class="mono">--ease-io</span>', '<span class="tnum">cubic-bezier(.65, 0, .2, 1)</span>', 'From rest to rest', 'The transition wipe, a glow pulsing once, the signature drawing on'),
                                                        ('<span class="mono">--ease-loop</span>', '<span class="tnum">cubic-bezier(.45, 0, .55, 1)</span>', 'Symmetrical, sine-like', 'Seamless loops only: the symbol’s point breathing, the loader at rest')], cls='xs', widths=['20mm', '40mm', 'auto', 'auto'])
    eq = '<p class="sm mt-2 muted">Lottie: --ease as handles o {.22, .8} i {.2, 1}. GSAP: CustomEase.create("sz", ".22,.8,.2,1"); power3.out is the nearest built-in. After Effects: keyframe velocity influence 22 % / 80 % out, 20 % / 100 % in.</p>'
    P.append(page('23 · Motion design', head('23.2 · Easing curves', 'Fast out, long <span class="lit">settle</span>.', 'Four curves; nothing else is used. The light curve carries the point across the wordmark S → E in about 0.5 s — leaving the A’s point as it passes and dropping the Z’s point into its ring — and spends the remaining 0.6 s arriving at the D’s point.') + body(ez + f'<div class="split mt-2" style="grid-template-columns:1fr 1fr"><div>{et}</div><div>{eq}</div></div>')))
    def strip(folder, base, times, label, h='h30'):
        return f'<div class="doc-h4 mt-2">{label}</div><div class="g6 gap-xs">' + ''.join(fig(A(f'{KF}{folder}/{base}/{base}--t{t}s.jpg', 800), f't = {t} s', None, None, plate='dark cover', h=h) for t in times) + '</div>'
    s1 = strip('Logo_Animations', 'sanzeed-logo-reveal--dark-1920x1080', ['0.00', '0.77', '1.57', '2.37', '3.17', '3.97'], 'Logo reveal · dark · 4 s — the point leaves the S, the letters bloom behind it, the A and Z points settle (the Z’s into its open ring), it becomes the D’s point; 1.2 s hold')
    s2 = strip('Logo_Animations', 'sanzeed-logo-outro--dark-1920x1080', ['0.00', '0.57', '1.17', '1.77', '2.37', '2.97'], 'Logo outro · 3 s — the letters fade, the symbol remains and grows uniformly to 2× (the only scale permitted, and only of the symbol)')
    s3 = strip('Logo_Animations', 'sanzeed-logo-reveal--light-1920x1080', ['0.00', '0.77', '1.57', '2.37', '3.17', '3.97'], 'Logo reveal · light (Plaster) — full-colour-light pairing, Old Gold glow at a third of the strength')
    P.append(page('23 · Motion design', head('23.3 · Logo reveal and outro — key frames', 'The letters are lit, not <span class="lit">drawn</span>.', 'Six key frames per piece from Exports/Key_Frames. Sources: Source_Files/logo-reveal/index.html (and index-light.html), logo-outro/index.html — CSS @keyframes, rendered deterministically by the kit’s capture_frames.js.') + body(s1 + s2 + s3)))
    s1 = strip('Lower_Thirds', 'sanzeed-lower-third--name--preview-1920x1080', ['0.00', '0.97', '1.97', '2.97', '3.97', '4.97'], 'Lower third · name + descriptor · 5 s (in 1.1 · hold 2.9 · out 0.4 · 0.6 empty), preview over an approved image; delivered with alpha as ProRes 4444 and WebM')
    s2 = strip('Lower_Thirds', 'sanzeed-lower-third--wall-label--preview-1920x1080', ['0.00', '0.97', '1.97', '2.97', '3.97', '4.97'], 'Lower third · wall label (project title + place)')
    io = '<div class="g5 gap-xs mt-2">' + fig(A(MO + 'Intros_Outros/sanzeed-intro--1920x1080--poster.jpg', 900), 'Intro · 6 s', '1920×1080 and 1080×1920', None, plate='dark cover', h='h26') + fig(A(MO + 'Intros_Outros/sanzeed-outro--1920x1080--poster.jpg', 900), 'End card · 6 s', '“Tell me about the room.” and the contact lines', None, plate='dark cover', h='h26') + fig(A(MO + 'Intros_Outros/sanzeed-transition--preview-1920x1080--poster.jpg', 900), 'Beam-wipe transition · 1.5 s', 'the only cut device; the hairline is the edit point', None, plate='dark cover', h='h26') + fig(A(MO + 'Lower_Thirds/sanzeed-lower-third--quote-attribution--preview-1920x1080--poster.jpg', 900), 'Lower third · quote attribution', '', None, plate='dark cover', h='h26') + fig(A(KF + 'Website_Loader/sanzeed-loader--960x120/sanzeed-loader--960x120--t0.77s.jpg', 900), 'Website loader · 2 s loop', 'CSS · SVG+SMIL · Lottie · GIF · MP4', None, plate='dark pad-sm', h='h26') + '</div>'
    P.append(page('23 · Motion design', head('23.4 · Lower thirds, intro, outro, transition', 'In, hold, <span class="lit">out</span>.', 'Three lower thirds with alpha, the branded intro and end card in 16:9 and 9:16, the beam-wipe transition and the website loader.') + body(s1 + s2 + io)))
    lr = table(['Rule', 'Detail'], [('<b>Never spin</b>', 'No rotation of any letter, dot or lockup, on any axis — including the “3D flip” and the “card turn”'), ('<b>Never bounce</b>', 'No overshoot, elastic or spring easing on the logo; the points settle from 1.6× to 1× on --ease'),
                                     ('<b>Never stretch</b>', 'No non-uniform scaling, skew, perspective, liquid or morph; the uniform scale in the outro is the only scale permitted, and only of the symbol'), ('<b>The points may glow</b>', 'The three points (A, Z, D) and the symbol’s point may carry the gold halo, pulse once (800 ms) and, in the symbol loop, breathe. Letters never glow'), ('<b>The Z’s ring stays open</b>', 'No halo, glow, fill or travelling point is ever drawn inside it: every source masks the glow with #zring (r 45.5 → 58.9 units), so the background always shows through'),
                                     ('<b>Left → right</b>', 'The travelling point leaves the S, passes through the Z’s ring and arrives at the D’s point; it never runs backwards'), ('<b>Revealed, not drawn</b>', 'Letters bloom (opacity, 400 ms) behind the light; never stroke-drawn, typed, split into particles or masked with anything but a straight edge'),
                                     ('<b>One reveal per piece</b>', 'An intro reveals it; an outro collapses it to the symbol. It never loops, flashes or re-enters'), ('<b>Pairing and clear space hold</b>', 'full-colour-dark on dark, full-colour-light on Plaster; clear space kept at every frame, including the glow'),
                                     ('<b>The travelling point exists only in motion</b>', 'r = 45 units (the size of the logo’s own points), Lamp Gold, 230-unit halo, at the height of the Z and D points; it never appears in a still')], cls='xs', widths=['40mm', 'auto'])
    dl = table(['Deliverable', 'Pixels', 'Length', 'Formats'], [('Logo reveal', '1920×1080 dark · light · 1080×1080 · 1080×1920', '4 s', 'MP4 · WebM · GIF'), ('Logo outro', '1920×1080', '3 s', 'MP4 · WebM · GIF'), ('Symbol loop · presentation logo', '1920×1080, transparent', '3 s · 4 s', 'MOV ProRes 4444 alpha · WebM alpha · MP4 / GIF on black'),
                                                                 ('Intro / end card', '1920×1080 · 1080×1920', '6 s', 'MP4 · WebM · GIF'), ('Transition', '1920×1080, transparent', '1.5 s', 'MOV alpha · WebM alpha · MP4 preview'), ('Stories · posts · stat counter', '1080×1920 · 1080×1080', '6 s · 5 s', 'MP4 · GIF'),
                                                                 ('Lower thirds', '1920×1080, transparent', '5 s', 'MOV alpha · WebM alpha · MP4 preview'), ('Website loader', '480×48 · 960×120', '2 s loop', 'CSS · SVG+SMIL · Lottie JSON · GIF · MP4')], cls='xs', widths=['36mm', 'auto', '14mm', '52mm'])
    sa = '<div class="g3 gap-xs mt-2">' + ''.join(fig(A(f'{MO}Social_Animations/{f}--poster.jpg', 700), t, None, None, plate='dark cover', h='h24') for f, t in [('sanzeed-story--project-reveal-1080x1920', 'Story · project reveal'), ('sanzeed-post--method-route-1080x1080', 'Post · the method as a route'), ('sanzeed-post--stat-counter-1080x1080', 'Stat counter')]) + '</div>'
    P.append(page('23 · Motion design', head('23.5 · Logo animation rules and delivery', 'The wordmark is never <span class="lit">transformed</span>.', 'It may be revealed, and its points may glow; nothing else. Codecs: MP4 H.264 CRF 20 · WebM VP9 · MOV ProRes 4444 straight alpha · GIF ≤ 960 px · 30 fps · Rec. 709. Every piece honours prefers-reduced-motion.') + body(f'<div class="split even"><div>{lr}</div><div>{dl}{sa}<p class="xs faint mt-2">New logo animation must be one of the approved pieces or derived from Source_Files/logo-reveal/index.html with only timing changed. Lottie JSON for the reveal and the loader imports into After Effects.</p></div></div>')))
    return P

# ------------------------------------------------------------------ 24 Brand voice & communication
def ch24():
    P = []
    P.append(divider('24', 'Brand voice &amp; <span class="lit">communication</span>.', 'A museum’s wall label, written by the person who built the room. Seven principles, eight tones, one vocabulary, a headline bank and the boilerplate — all from 01_BRAND_STRATEGY.',
        [('24.1', 'Voice principles'), ('24.2', 'Tone by situation'), ('24.3', 'Vocabulary and mechanics'), ('24.4', 'Headline bank, boilerplate, calls to action')], '24 · Brand voice'))
    vp = table(['Principle', 'Do', 'Example from sanzeed.com'], [
        ('<b>First person, singular</b>', '“I”, “me”, “my”. The brand is one person.', '“I lead the whole room — story, space, graphics, media and the team that builds it.”'),
        ('<b>Short sentences, long ideas</b>', 'One thought per sentence. Let a full stop land.', '“The script comes first. Every room, screen and surface carries a line of it.”'),
        ('<b>Name the deliverable</b>', 'Say what the client receives, concretely.', '“You receive a concept book and a walkthrough film.”'),
        ('<b>Spatial vocabulary</b>', 'Rooms, routes, thresholds, galleries, light, dwell time, opening night.', '“Galleries planned as a route, not a floor plan.”'),
        ('<b>End on the image</b>', 'Finish paragraphs on a picture, not a claim.', '“Visitors walk the whole line of leaders without a map, and come out knowing the order by heart.”'),
        ('<b>Plain numbers</b>', 'Numerals, no inflation.', '“90 projects, one continuous craft.”'),
        ('<b>Warm, not casual</b>', 'Hospitable; never slangy or jokey.', '“Tell me about the room. A few lines are enough.”')], widths=['36mm', '70mm', 'auto'])
    tests = '<div class="callout mt-3"><b class="k">Three tests for any new copy.</b> Could this be read aloud, calmly, in a museum lobby? · Does it name a room, a route, a light or a deliverable? · Would deleting the adjectives make it stronger? (If yes, delete them.)</div>'
    P.append(page('24 · Brand voice', head('24.1 · Voice principles', 'The voice in one <span class="lit">line</span>.', 'Precise, calm, first person, short. From Brand_Voice_and_Tone.md; every example is confirmed copy from the site.') + body(vp + tests)))
    ts = table(['Situation', 'Tone dial', 'Example'], [
        ('Website headline / hero', 'Monumental, quiet', '“Experiential design you can walk into.”'), ('Case study', 'Documentary, sequenced (The brief · The idea · The walk · What visitors do)', '“A corridor you walk in order.”'),
        ('Proposal / quotation', 'Precise, deliverable-led, no adjectives', '“Step 02 — Direct. You receive a concept book and a walkthrough film.”'), ('Email / WhatsApp reply', 'Warm, brief, specific next step', '“Thank you for writing. I’ve read the brief twice. Could we speak on Thursday for twenty minutes?”'),
        ('LinkedIn post', 'Observational, one insight, one image', '“The spine of the museum is a single long passage. The building tells the story before any gallery does.”'), ('Social caption', 'Wall-label: title, place, one line', '“Ram Katha Show · Ayodhya. The script came first.”'),
        ('Error / empty states', 'Helpful, unhurried', '“Nothing in this room yet. Try another filter or clear the search.”'), ('Thank-you / after opening', 'Personal, signed', '“The doors are open. Thank you for trusting me with the room. — Sanzeed.”')], widths=['40mm', '66mm', 'auto'])
    ex = '<div class="g3 gap-sm mt-3">' + fig(A('08_SOCIAL_MEDIA/LinkedIn/sanzeed-li-post--insight-1200x627.png', 900), 'LinkedIn · observational', '', None, plate='plaster cover', h='h30') + fig(A('07_WEBSITE_DIGITAL_ASSETS/UI_Components/renders/ui-kit--1440.png', 900, crop=(0, 17950, 1440, 18700)), 'Empty state · unhurried', 'ui-kit 018', None, plate='dark cover top', h='h30') + fig(A('09_PRINT_STATIONERY/Thank_You_Cards/sanzeed-thank-you-card--folded-inside.png', 900), 'Thank-you · personal, signed', '', None, plate='plaster cover', h='h30') + '</div>'
    P.append(page('24 · Brand voice', head('24.2 · Tone by situation', 'One voice, eight <span class="lit">dials</span>.', 'The voice does not change; the dial does. Monumental on the hero, documentary in a case study, warm in a reply.') + body(ts + ex)))
    voc = ('<div class="doc-h3">Use</div><p style="font-size:11pt;line-height:1.6">room · route · threshold · gallery · walk · light · lit · carry · opening night · wall label · visitor’s book · the one central story · concept book · walkthrough film · prototype room · calm · held in one hand · monumental</p>'
           '<div class="doc-h3 mt-4">Avoid</div><p style="font-size:11pt;line-height:1.6;color:var(--fg-2)"><s>cutting-edge</s> · <s>innovative</s> · <s>world-class</s> · <s>synergy</s> · <s>leverage</s> · <s>immersive</s> (as a filler adjective — only as the named service) · <s>solutions</s> · <s>best-in-class</s> · <s>passionate</s> · <s>360°</s> · <s>wow</s></p>')
    mech = table(['Mechanic', 'Rule'], [('Headlines', 'Sentence case, end with a full stop. The last word may be set in the muted or gold colour (“Eight rooms, lit.”)'), ('Eyebrows', 'Small caps, letter-spaced, gold: NOW SHOWING · METHOD · ABOUT · JOURNEY · GET IN TOUCH'),
                                       ('Counters', 'Three digits, “001”. Steps: “STEP 01”'), ('Dashes', 'Spaced em dash on the website ( — ); en dash for ranges (2018 – 2026)'), ('Currency', '₹ with Indian grouping (₹25 lakh, ₹1 crore)'),
                                       ('Dates', '“Aug 2026 — Present”; “5 November 2026” in documents'), ('Sign-off', '“— Sanzeed Mirza” (quotes) · “Sanzeed.” (signature mark) · “Sanzeed Mirza · Experiential Design Consultant” (formal)'),
                                       ('Naming', 'SANZEED / Sanzeed / @sanzeed for the mark and handles; Sanzeed Mirza for anything formal; never “Sanzeed Studio”')], widths=['24mm', 'auto'])
    P.append(page('24 · Brand voice', head('24.3 · Vocabulary and mechanics', 'Words from the <span class="lit">room</span>.', 'The words the brand uses and the words it never does; the typographic mechanics that make copy look like Sanzeed before it is read.') + body(f'<div class="split even"><div>{voc}</div><div>{mech}</div></div>')))
    hb = ['Experiential design you can walk into.', 'Vision you can walk into.', 'Eight rooms, lit.', 'Between two points of light.', 'A method for the monumental.', '90 projects, one continuous craft.', 'Strategy, craft and calm leadership, in one person.', 'Fifteen years, one through-line.', 'Let’s shape something that endures.', 'Tell me about the room.', 'Carry the light across.', 'One vision, from the brief to opening night.', 'The script comes first.', 'Galleries planned as a route, not a floor plan.']
    bank = '<div class="doc-h3">Headline bank · approved style</div><div style="columns:2;column-gap:8mm">' + ''.join(f'<div class="ff-display mid" style="font-size:12.5pt;line-height:1.25;padding:1.4mm 0;border-bottom:1px solid var(--line);break-inside:avoid">{lit(h)}</div>' for h in hb) + '</div>'
    boil = ('<div class="doc-h3">Boilerplate · press and media kit</div><p class="measure">Sanzeed Mirza is an Experiential Design Consultant based in New Delhi, working with institutions and brands wherever the project is. Over fifteen years he has directed more than 90 projects, including 60+ museums and experience centres and 15 projection-mapping and light shows, among them the Prime Minister Museum in New Delhi, the Ram Katha Show in Ayodhya and Buddha Park in Uttarakhand. He works independently with museums, cultural institutions and brands as creative lead from first concept to opening day. sanzeed.com</p>'
            '<div class="doc-h3 mt-3">Elevator messages</div><p><b class="k">10 words</b> · Experiential design consultant. Museums, pavilions and shows you can walk into.</p><p class="mt-1"><b class="k">25 words</b> · Sanzeed Mirza is an independent experiential design consultant in New Delhi. Fifteen years in, he leads the whole room — story, space, media and team — for institutions and brands.</p>'
            '<div class="doc-h3 mt-3">Calls to action</div>' + table(['Primary', 'Secondary', 'Tertiary'], [('Tell me about the room →', 'See the work', 'WhatsApp @sanzeed'), ('Write in the visitor’s book →', 'About Sanzeed', 'Save contact'), ('Get in touch', 'Watch the film', 'LinkedIn')], cls='xs')
            + '<p class="sm mt-2"><b class="k">Response promises</b> · “The first conversation is always free.” · “I reply within two working days.” · “If it is urgent, WhatsApp is fastest.”</p>')
    P.append(page('24 · Brand voice', head('24.4 · Headline bank, boilerplate, calls to action', 'Lines that are already <span class="lit">approved</span>.', 'Use these verbatim before writing new ones. New headlines follow the same mechanics and pass the three tests.') + body(f'<div class="split" style="grid-template-columns:1fr 1fr">{"<div>"+bank+"</div>"}<div>{boil}</div></div>')))
    return P

