# ------------------------------------------------------------------ 26 File formats, naming & production
def folder_stats():
    out = []
    for d in sorted(os.listdir(ROOT)):
        p = os.path.join(ROOT, d)
        if not os.path.isdir(p) or not d[:2].isdigit(): continue
        n = 0; sz = 0
        for r, _, fs in os.walk(p):
            for f in fs: n += 1; sz += os.path.getsize(os.path.join(r, f))
        out.append((d, n, sz / 1e6))
    return out

